import pytest

from bedrock_protocol import v975, v1001, v2168

EMPTY_ITEM_BLOB = bytes(10)

# generated by gophertunnel de090ae:
# packet.InventoryContent{WindowID: 12,
#   Content: []protocol.ItemInstance{{Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 1}, Count: 64,
#   BlockRuntimeID: 7}}, {}},
#   Container: protocol.FullContainerName{ContainerID: 59, DynamicContainerID: protocol.Option[uint32](3)},
#   StorageItem: protocol.ItemInstance{}}
V975 = bytes.fromhex("0c0202400000000e0a00000000000000000000003b010300000000")

# generated by gophertunnel 654cd5f:
# packet.InventoryContent{WindowID: 12,
#   Content: []protocol.ItemInstance{{Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 1}, Count: 64,
#   BlockRuntimeID: 7}}, {}},
#   Container: protocol.FullContainerName{ContainerID: 59, DynamicContainerID: protocol.Option[uint32](3)},
#   StorageItem: protocol.ItemInstance{}}
V1001 = bytes.fromhex("0c02010040000000070a0000000000000000000000000000000000003b01030000000000000000000000")

# generated by gophertunnel b8bd735:
# packet.InventoryContent{WindowID: 12,
#   Content: []protocol.ItemInstance{{Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 1}, Count: 64,
#   BlockRuntimeID: 7}}, {}},
#   Container: protocol.FullContainerName{ContainerID: 59, DynamicContainerID: protocol.Option[uint32](3)},
#   StorageItem: protocol.ItemInstance{}}
V2168 = bytes.fromhex("0c02010040000000070a0000000000000000000000000000000000003b01030000000000000000000000")

# generated by gophertunnel b8bd735:
# packet.InventoryContent{WindowID: 12, Content: []protocol.ItemInstance{{StackNetworkID: 9,
#   Stack: protocol.ItemStack{ItemType: protocol.ItemType{NetworkID: 5, MetadataValue: 3}, Count: 1}}, {}},
#   Container: protocol.FullContainerName{ContainerID: 59, DynamicContainerID: protocol.Option[uint32](3)},
#   StorageItem: protocol.ItemInstance{}}
V2168_NET_ID = bytes.fromhex("0c0205000100030112000a0000000000000000000000000000000000003b01030000000000000000000000")

# generated by gophertunnel 6353c49:
# packet.InventoryContent{Container: protocol.FullContainerName{ContainerID: 29}}
V1001_ABSENT_DYNAMIC_ID = bytes.fromhex("00001d000000000000000000")

V2168_OUT_OF_RANGE_WINDOW = bytes.fromhex("ac02") + V2168[1:]

GOLDENS = [
    pytest.param(
        v975.InventoryContentPacket(
            inventory_id=12,
            slots=[
                v975.NetworkItemStackDescriptor(
                    id=1, stack_size=64, block_runtime_id=7, user_data_buffer=EMPTY_ITEM_BLOB
                ),
                v975.NetworkItemStackDescriptor(),
            ],
            full_container_name=v975.FullContainerName(name=v975.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.InventoryContentPacket(
            inventory_id=12,
            slots=[
                v1001.SerializedNetworkItemStackDescriptor(
                    id=1, stack_size=64, block_runtime_id=7, user_data_buffer=EMPTY_ITEM_BLOB
                ),
                v1001.SerializedNetworkItemStackDescriptor(),
            ],
            full_container_name=v1001.FullContainerName(name=v1001.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v2168.InventoryContentPacket(
            inventory_id=12,
            slots=[
                v2168.SerializedNetworkItemStackDescriptor(
                    id=1, stack_size=64, block_runtime_id=7, user_data_buffer=EMPTY_ITEM_BLOB
                ),
                v2168.SerializedNetworkItemStackDescriptor(),
            ],
            full_container_name=v2168.FullContainerName(name=v2168.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
        ),
        V2168,
        id="v2168",
    ),
    pytest.param(
        v2168.InventoryContentPacket(
            inventory_id=12,
            slots=[
                v2168.SerializedNetworkItemStackDescriptor(
                    id=5, stack_size=1, aux_value=3, net_id_variant=9, user_data_buffer=EMPTY_ITEM_BLOB
                ),
                v2168.SerializedNetworkItemStackDescriptor(),
            ],
            full_container_name=v2168.FullContainerName(name=v2168.ContainerEnumName.CURSOR_CONTAINER, dynamic_id=3),
        ),
        V2168_NET_ID,
        id="v2168-net-id",
    ),
    pytest.param(
        v1001.InventoryContentPacket(
            full_container_name=v1001.FullContainerName(name=v1001.ContainerEnumName.INVENTORY_CONTAINER),
        ),
        V1001_ABSENT_DYNAMIC_ID,
        id="v1001-absent-dynamic-id",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168])
def test_inventory_content_is_packet_49(version):
    assert version.PACKETS[49] is version.InventoryContentPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_inventory_content_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_inventory_content_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_inventory_content_is_the_same_bytes_at_1001_and_2168_when_no_slot_has_a_net_id():
    assert V2168 == V1001


def test_inventory_content_rejects_a_window_id_outside_its_integer_range():
    with pytest.raises(ValueError, match="at byte"):
        v2168.InventoryContentPacket.from_bytes(V2168_OUT_OF_RANGE_WINDOW)


def test_inventory_content_keeps_a_negative_window_id_through_the_wire():
    packet = v2168.InventoryContentPacket(inventory_id=-2)
    assert v2168.InventoryContentPacket.from_bytes(bytes(packet)) == packet


def test_inventory_content_2168_net_id_body_is_rejected_at_1001():
    with pytest.raises(ValueError, match="at byte"):
        v1001.InventoryContentPacket.from_bytes(V2168_NET_ID)
